pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);

        vm.deal(alice, 10 wei);
        vm.prank(alice);
        c.addToBalance{value: 10 wei}();

        vm.deal(bob, 100 wei);
        vm.prank(bob);
        c.addToBalance{value: 100 wei}();

        vm.prank(alice);
        c.withdrawBalance();

        uint256 aliceBalance = c.getBalance(alice);
        assertTrue(aliceBalance == 0);
    }
}
